('OTHER_ENGINEERING',R(r"mechanical|electrical|civil|hardware|manufacturing engineer|process engineer|quality engineer|industrial engineer|chemical|aerospace|structural|biomedical|facilities engineer|field engineer|quality|test engineer|validation engineer|design engineer|systems? engineer|electronics|rf engineer|\bpackaging engineer|reliability engineer|project engineer|production engineer|engineering technician|environmental engineer|optical|semiconductor|process development|\bengineer\b|engineering")),
