('CLERICAL_ADMIN',R(r"administrative|admin (?:assistant|specialist|coordinator|support|associate)|\badmin\b|receptionist|data entry|office (?:assistant|clerk|coordinator|support|associate|admin)|clerk|secretary|executive assistant|personal assistant|accounts? (?:payable|receivable)|\bap\b|\bar\b|billing|payroll|book ?keep|scheduler|scheduling|back office|claims? (?:processor|examiner|specialist|adjuster|representative)|processor|document (?:control|specialist)|records|file clerk|mail|front desk|office manager(?!x)|clerical|dispatcher|insurance (?:specialist|processor|representative)|medical (?:biller|coder|records|receptionist|secretary)|virtual assistant|assistant to|order (?:entry|processor)|data processor")),
