_ORDER=['AI_DATA_WORK','AI_PRODUCER','PRODUCT_DESIGN','MANAGEMENT','CUSTOMER_SUPPORT','SOFTWARE_ENG','DATA_ENG_ANALYTICS','OTHER_ENGINEERING','CLERICAL_ADMIN','PROF_EXPOSED','HEALTH_CLINICAL','EDUCATION','SKILLED_TRADE','FRONTLINE_SERVICE','SALES_BIZ']
_D=dict(RULES); RULES=[(k,_D[k]) for k in _ORDER]
FALLBACK=re.compile(r"\bassistant\b|coordinator",re.I)
def classify_title(title,company_norm=''):
    if not isinstance(title,str) or not title.strip() or re.fullmatch(r'\W*(any?o?nymous|anyonymous)( employee)?\W*(former employee)?\W*|former employee|employee|current employee',title.strip().lower()): return 'MISSING_TITLE','missing'
    t=title.strip().lower()
    t=re.sub(r"\s*[-,/(].*$","",t) if False else t
    # pure intern / generic
    for cls,rx in RULES:
        if cls=='MANAGEMENT':
            # special cases that are not management
            if re.search(r"account manager|marketing manager|product marketing|manager of (?:marketing|sales)|customer (?:service|success|support) manager|sales manager|operations? manager(?!x)",t) and not re.search(r"director|vp|head|general manager",t):
                pass
        if rx.search(t):
            if cls=='MANAGEMENT':
                if re.search(r"account manager|account management|relationship manager|client manager",t): return 'SALES_BIZ','rule'
                if re.search(r"marketing manager|content manager|brand manager|communications manager|social media manager|recruit\w* manager|hr manager|talent",t): return 'PROF_EXPOSED','rule'
                if re.search(r"engineering manager|software (?:development )?manager|manager,? software",t): return 'MANAGEMENT','rule'
            if cls=='SOFTWARE_ENG' and re.search(r"\bit\b",t) and not re.search(r"software|developer|programmer|\bit (?:support|specialist|analyst|technician|engineer|help|manager|administrator|consultant|auditor)|information tech",t): continue
            if cls=='OTHER_ENGINEERING' and re.fullmatch(r"(?:(?:senior|staff|principal|lead|sr\.?|jr\.?|junior|associate|sr\.? staff|senior staff) )*engineer(?: [ivx0-9]+)?",t) and company_norm in TECH_CO:
                return 'SOFTWARE_ENG','rule(tech-co engineer)'
            return cls,'rule'
    if FALLBACK.search(t): return 'CLERICAL_ADMIN','fallback(assistant/coordinator)'
    if re.search(r"intern|trainee|apprentice|student",t): return 'OTHER','intern/generic'
    return 'OTHER','unmatched'
